/* Search across every TechTools365 tool. The index is generated by shared/brand/sync.py
   and only loads when someone first uses the box. */
(function () {
  var box = document.querySelector('[data-search]');
  if (!box) return;
  var input = box.querySelector('input');
  var list = box.querySelector('ul');
  var data = null;
  var matches = [];
  var active = -1;

  function load() {
    if (data) return Promise.resolve(data);
    return fetch('/search-index.json')
      .then(function (r) { return r.json(); })
      .then(function (json) { data = json; return data; });
  }

  function search(q) {
    var words = q.toLowerCase().split(/\s+/).filter(Boolean);
    if (!words.length) return [];
    return data
      .map(function (d) {
        var name = d.n.toLowerCase();
        var all = (d.n + ' ' + d.s + ' ' + d.t).toLowerCase();
        if (!words.every(function (w) { return all.indexOf(w) !== -1; })) return null;
        var inName = words.filter(function (w) { return name.indexOf(w) !== -1; }).length;
        var score = inName * 2 + (name.indexOf(words[0]) === 0 ? 3 : 0);
        return { d: d, score: score };
      })
      .filter(Boolean)
      .sort(function (a, b) { return b.score - a.score; })
      .slice(0, 8)
      .map(function (m) { return m.d; });
  }

  function close() {
    list.hidden = true;
    active = -1;
    input.setAttribute('aria-expanded', 'false');
    input.removeAttribute('aria-activedescendant');
  }

  function paintActive() {
    Array.prototype.forEach.call(list.children, function (li, i) {
      li.classList.toggle('is-active', i === active);
      li.setAttribute('aria-selected', i === active ? 'true' : 'false');
    });
    if (active >= 0) input.setAttribute('aria-activedescendant', list.children[active].id);
    else input.removeAttribute('aria-activedescendant');
  }

  function render() {
    var q = input.value.trim();
    list.textContent = '';
    active = -1;
    if (!q) { close(); return; }
    load().then(function () {
      if (input.value.trim() !== q) return;
      list.textContent = '';
      matches = search(q);
      if (!matches.length) {
        var none = document.createElement('li');
        none.className = 'search-none';
        none.textContent = 'Nothing matches that. Try a shorter word.';
        list.appendChild(none);
      }
      matches.forEach(function (m, i) {
        var li = document.createElement('li');
        li.id = list.id + '-' + i;
        li.setAttribute('role', 'option');
        var a = document.createElement('a');
        a.href = m.p;
        a.tabIndex = -1;
        var name = document.createElement('b');
        name.textContent = m.n;
        var site = document.createElement('em');
        site.textContent = m.s;
        a.appendChild(name);
        a.appendChild(site);
        li.appendChild(a);
        list.appendChild(li);
      });
      list.hidden = false;
      input.setAttribute('aria-expanded', 'true');
      paintActive();
    });
  }

  input.addEventListener('input', render);
  input.addEventListener('focus', function () { load(); if (input.value.trim()) render(); });
  input.addEventListener('keydown', function (e) {
    if (e.key === 'ArrowDown' || e.key === 'ArrowUp') {
      if (!matches.length) return;
      e.preventDefault();
      active = (active + (e.key === 'ArrowDown' ? 1 : -1) + matches.length) % matches.length;
      paintActive();
    } else if (e.key === 'Enter') {
      var pick = matches[active >= 0 ? active : 0];
      if (pick && !list.hidden) { e.preventDefault(); location.href = pick.p; }
    } else if (e.key === 'Escape') {
      close();
    }
  });
  document.addEventListener('pointerdown', function (e) { if (!box.contains(e.target)) close(); });
})();
